/// Absorbs data into a SHA-3 or SHAKE computation: if the state `*state` represents a message whose length is `pos` modulo `rate` (`VG.Spec.Sha3.Repr`), it then represents that message followed by the `len` bytes at `data`. Returns the position after them, `(pos + len) % rate`.
///
/// Contract: `VG.Spec.Sha3.absorbContract`. Constant time: only the pointers, `rate`, `pos` and `len` may affect timing, not the state or the data.
///
/// The function uses no stack: it saves its return address in `scratch`.
///
/// # Safety
///
/// * `state` must be valid for reads and writes of 200 bytes.
/// * `data` must be valid for reads of `len` bytes.
/// * `scratch` must be valid for reads and writes of 640 bytes.
/// * `rate` must be 72, 104, 136, 144 or 168, and `pos` less than `rate`.
/// * The contents of `scratch` on return are unspecified.
/// * `state` and `scratch` must not overlap each other, `data` or the arguments on the stack (distinct Rust objects never do).
/// * None of `state`, `data` and `scratch` may wrap around the end of the address space (no Rust object does).
#[unsafe(naked)]
pub(crate) unsafe extern "C" fn vg_keccak_absorb(state: *mut [u64; 25], rate: usize, pos: usize, data: *const u8, len: usize, scratch: *mut [u64; 80]) -> usize {
    core::arch::naked_asm!(
        "ldr r12, [sp, #4]",
        "str r4, [r12, #512]",
        "str r5, [r12, #516]",
        "str r6, [r12, #520]",
        "str r7, [r12, #524]",
        "str lr, [r12, #528]",
        "mov r4, r1",
        "mov r1, r12",
        "mov r5, r2",
        "mov r6, r3",
        "ldr r7, [sp, #0]",
        "cmp r7, #0",
        "beq 20f",
        "22:",
        "ldrb r2, [r6, #0]",
        "add r3, r0, r5",
        "ldrb r12, [r3, #0]",
        "eor r2, r2, r12",
        "strb r2, [r3, #0]",
        "add r6, r6, #1",
        "add r5, r5, #1",
        "sub r7, r7, #1",
        "cmp r5, r4",
        "beq 23f",
        "b 24f",
        "23:",
        "mov r5, #0",
        "bl {vg_keccak_f1600}",
        "24:",
        "cmp r7, #0",
        "bne 22b",
        "b 21f",
        "20:",
        "21:",
        "mov r0, r5",
        "ldr r4, [r1, #512]",
        "ldr r5, [r1, #516]",
        "ldr r6, [r1, #520]",
        "ldr r7, [r1, #524]",
        "ldr lr, [r1, #528]",
        "bx lr",
        vg_keccak_f1600 = sym super::sha3::vg_keccak_f1600,
    )
}

/// Pads a SHA-3 or SHAKE message: if the state `*state` represents a message whose length is `pos` modulo `rate` (`VG.Spec.Sha3.Repr`), it becomes the state after absorbing that message with the domain-separation suffix (the low byte of `suffix`, with the first bit of the padding: `0x06` for SHA-3, `0x1f` for SHAKE) and `pad10*1`.
///
/// Contract: `VG.Spec.Sha3.padContract`. Constant time: only the pointers, `rate`, `pos` and `suffix` may affect timing, not the state.
///
/// The function uses no stack: it saves its return address in `scratch`.
///
/// # Safety
///
/// * `state` must be valid for reads and writes of 200 bytes.
/// * `scratch` must be valid for reads and writes of 640 bytes.
/// * `rate` must be 72, 104, 136, 144 or 168, and `pos` less than `rate`.
/// * The contents of `scratch` on return are unspecified.
/// * `state` and `scratch` must not overlap each other or the arguments on the stack (distinct Rust objects never do).
/// * Neither `state` nor `scratch` may wrap around the end of the address space (no Rust object does).
#[unsafe(naked)]
pub(crate) unsafe extern "C" fn vg_keccak_pad(state: *mut [u64; 25], rate: usize, pos: usize, suffix: u32, scratch: *mut [u64; 80]) {
    core::arch::naked_asm!(
        "ldr r12, [sp, #0]",
        "str lr, [r12, #512]",
        "add r2, r0, r2",
        "ldrb lr, [r2, #0]",
        "eor lr, lr, r3",
        "strb lr, [r2, #0]",
        "add r2, r0, r1",
        "sub r2, r2, #1",
        "ldrb lr, [r2, #0]",
        "eor lr, lr, #128",
        "strb lr, [r2, #0]",
        "mov r1, r12",
        "bl {vg_keccak_f1600}",
        "ldr lr, [r1, #512]",
        "bx lr",
        vg_keccak_f1600 = sym super::sha3::vg_keccak_f1600,
    )
}

